#!/usr/bin/env node
/**
 * Bundles the @xterm/xterm UMD JS + @xterm/addon-fit UMD JS + xterm.css into
 * a single JS asset (src/assets/xterm-bundle.generated.js) that exports the
 * three payloads as plain strings. The XtermTerminal component splices them
 * into an HTML document handed to react-native-webview.
 *
 * Re-run this when bumping xterm versions. The generated file is committed,
 * so Expo Go / Metro don't need this script at runtime.
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const OUT_DIR = path.join(ROOT, 'src', 'assets');
const OUT_FILE = path.join(OUT_DIR, 'xterm-bundle.generated.js');

const XTERM_JS = fs.readFileSync(
  path.join(ROOT, 'node_modules', '@xterm', 'xterm', 'lib', 'xterm.js'),
  'utf8',
);
const FIT_JS = fs.readFileSync(
  path.join(ROOT, 'node_modules', '@xterm', 'addon-fit', 'lib', 'addon-fit.js'),
  'utf8',
);
const XTERM_CSS = fs.readFileSync(
  path.join(ROOT, 'node_modules', '@xterm', 'xterm', 'css', 'xterm.css'),
  'utf8',
);

const pkgVersion = (mod) => {
  try {
    return require(path.join(ROOT, 'node_modules', mod, 'package.json')).version;
  } catch {
    return 'unknown';
  }
};

fs.mkdirSync(OUT_DIR, { recursive: true });

const body = `// AUTO-GENERATED by scripts/build-xterm-bundle.js — do not edit.
// @xterm/xterm ${pkgVersion('@xterm/xterm')}  @xterm/addon-fit ${pkgVersion('@xterm/addon-fit')}

export const XTERM_JS = ${JSON.stringify(XTERM_JS)};
export const XTERM_FIT_JS = ${JSON.stringify(FIT_JS)};
export const XTERM_CSS = ${JSON.stringify(XTERM_CSS)};
`;

fs.writeFileSync(OUT_FILE, body);
console.log(
  `wrote ${path.relative(ROOT, OUT_FILE)} (${(body.length / 1024).toFixed(1)} KB)`,
);
